enum LoadState {
    case loading
    case loaded([Post])
    case failed(Error)
}

func render(_ state: LoadState) {
    switch state {
    case .loading:               showSpinner()
    case .loaded(let posts) where posts.isEmpty: showEmpty()
    case .loaded(let posts):     show(posts)
    case .failed(let error):     showError(error)
    }
}

